#!/bin/bash
# SecureXL rate limiting profile 'Basic' for A-DMZ (192.168.12.101)
# Generated by the SecureXL Rate Limiting portal.
#
# Run in Expert mode on EACH cluster member:  bash admz-basic.sh
# Pass --dry-run to print the commands without running them.
# Removes existing rules named 'ADMZ-*' first, and only those.

PREFIX='ADMZ-'
DRY=0; [ "$1" = "--dry-run" ] && DRY=1

run() {
    echo "+ $*"
    [ $DRY -eq 1 ] && return 0
    "$@" || echo "  !! failed (exit $?) - check the syntax for this build with: fwaccel dos rate -h"
}

echo "== Removing previous lab rules ($PREFIX*) =="
fwaccel dos rate get | grep "name=$PREFIX" | sed -n 's/.*uid=\(<[^>]*>\|[^ ]*\).*/\1/p' |
while read -r uid; do run fwaccel dos rate del "$uid"; done

echo "== Installing profile 'Basic' =="
run fwaccel dos rate add -a d -n ADMZ-BAS-pkt-src destination cidr:192.168.12.101/32 pkt-rate 20000 track source
run fwaccel dos rate add -a d -n ADMZ-BAS-http-conn destination cidr:192.168.12.101/32 service 6/80 new-conn-rate 150 track source
run fwaccel dos rate add -a d -n ADMZ-BAS-https-conn destination cidr:192.168.12.101/32 service 6/443 new-conn-rate 150 track source
run fwaccel dos rate add -a d -n ADMZ-BAS-ssh-conn destination cidr:192.168.12.101/32 service 6/22 new-conn-rate 10 track source
run fwaccel dos rate add -a d -n ADMZ-BAS-concurrent destination cidr:192.168.12.101/32 concurrent-conns 1000 track source
run fwaccel dos rate add -a n -n ADMZ-BAS-aggregate destination cidr:192.168.12.101/32 pkt-rate 60000
run fwaccel dos pbox --set-drops-threshold 1000
run fwaccel dos pbox --set-timeout 60
run fwaccel dos pbox --set-log-drops on
run fwaccel dos pbox --set-enabled on

echo "== Result =="
fwaccel dos rate get
fwaccel dos pbox --show-config
